import type { MetadataRoute } from "next";

// PWA manifest (NFR-01, AC-1.1, AC-1.2). Icons are generated by `npm run icons`.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "SprintYourLife",
    short_name: "SprintYourLife",
    description: "Personal sprints for sidequests: what can I do right now?",
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: "#18181b",
    theme_color: "#18181b",
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png" },
    ],
  };
}
